def give_existing_customers_a_qid(apps, schema_editor):
    """Demo customers created before QIDs existed get a synthetic QID in the reserved 299 range."""
    Counterparty = apps.get_model("foundation", "SyntheticCounterparty")
    for customer in Counterparty.objects.filter(party_type="customer", qid__isnull=True).order_by("pk"):
        customer.qid = f"299{customer.pk:08d}"
        customer.save(update_fields=["qid"])


